[{"nome": "admin_delete_user", "tipo": "funcao", "esquema": "public", "retorno": "void", "definicao": "CREATE OR REPLACE FUNCTION public.admin_delete_user(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE id = auth.uid()
      AND role = 'admin'
      AND ativo = TRUE
  ) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  IF p_user_id = auth.uid() THEN
    RAISE EXCEPTION 'cannot delete self';
  END IF;

  DELETE FROM public.profiles WHERE id = p_user_id;
  DELETE FROM auth.users WHERE id = p_user_id;
END;
$function$
", "linguagem": "plpgsql", "argumentos": "p_user_id uuid", "comentario": null, "configuracao": ["search_path=public, auth"], "volatilidade": "volatile", "security_definer": true}, {"nome": "admin_delete_user_by_email", "tipo": "funcao", "esquema": "public", "retorno": "void", "definicao": "CREATE OR REPLACE FUNCTION public.admin_delete_user_by_email(p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  v_user_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE id = auth.uid()
      AND role = 'admin'
      AND ativo = TRUE
  ) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  SELECT id INTO v_user_id FROM auth.users WHERE email = p_email;
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  IF v_user_id = auth.uid() THEN
    RAISE EXCEPTION 'cannot delete self';
  END IF;

  DELETE FROM public.profiles WHERE id = v_user_id;
  DELETE FROM auth.users WHERE id = v_user_id;
END;
$function$
", "linguagem": "plpgsql", "argumentos": "p_email text", "comentario": null, "configuracao": ["search_path=public, auth"], "volatilidade": "volatile", "security_definer": true}, {"nome": "camara_from_servicos", "tipo": "funcao", "esquema": "public", "retorno": "text", "definicao": "CREATE OR REPLACE FUNCTION public.camara_from_servicos(p_servicos text[])
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caters TEXT[] := ARRAY['Manejo de Resíduos Sólidos', 'Limpeza Urbana'];
  v_catesa TEXT[] := ARRAY['Abastecimento de Água', 'Esgotamento Sanitário', 'Drenagem'];
  v_has_caters BOOLEAN := FALSE;
  v_has_catesa BOOLEAN := FALSE;
BEGIN
  IF p_servicos IS NULL OR array_length(p_servicos, 1) IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT
    EXISTS (SELECT 1 FROM unnest(p_servicos) s WHERE s = ANY(v_caters)),
    EXISTS (SELECT 1 FROM unnest(p_servicos) s WHERE s = ANY(v_catesa))
  INTO v_has_caters, v_has_catesa;

  IF     v_has_caters AND NOT v_has_catesa THEN RETURN 'caters';
  ELSIF  v_has_catesa AND NOT v_has_caters THEN RETURN 'catesa';
  ELSE   RETURN NULL; -- mixed or unknown → legacy, visible to all
  END IF;
END;
$function$
", "linguagem": "plpgsql", "argumentos": "p_servicos text[]", "comentario": null, "configuracao": ["search_path=public"], "volatilidade": "stable", "security_definer": true}, {"nome": "can_access_camara", "tipo": "funcao", "esquema": "public", "retorno": "boolean", "definicao": "CREATE OR REPLACE FUNCTION public.can_access_camara(row_camara text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT (
    public.get_my_role() = 'admin'
    OR (
      public.get_my_role() IN ('coordenador', 'fiscal')
      AND (
        public.get_my_camara_tecnica() IS NULL  -- no chamber = backward compat, see all
        OR row_camara IS NULL                   -- legacy record
        OR row_camara = public.get_my_camara_tecnica()
      )
    )
  );
$function$
", "linguagem": "sql", "argumentos": "row_camara text", "comentario": null, "configuracao": ["search_path=public"], "volatilidade": "stable", "security_definer": true}, {"nome": "caters_import_from_fiscalizacao", "tipo": "funcao", "esquema": "public", "retorno": "integer", "definicao": "CREATE OR REPLACE FUNCTION public.caters_import_from_fiscalizacao(p_fiscalizacao_id uuid, p_caters_process_id uuid, p_prazo_dias integer DEFAULT 30)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_data_base     date;
  v_prazo_date    date;
  v_rec           RECORD;
  v_det           RECORD;
  v_imported      integer := 0;
BEGIN
  -- Verifica se o caller tem acesso CATERS
  IF NOT public.is_caters_user() THEN
    RAISE EXCEPTION 'Acesso negado: usuário não pertence à CATERS.';
  END IF;

  -- Data base para calcular o prazo de 30 dias das recomendações
  SELECT COALESCE(data_fim::date, data_inicio::date, now()::date)
    INTO v_data_base
    FROM public.fiscalizacoes
   WHERE id = p_fiscalizacao_id;

  v_prazo_date := v_data_base + (p_prazo_dias || ' days')::interval;

  -- ----------------------------------------------------------------
  -- Importar RECOMENDAÇÕES (fonte atual)
  -- ----------------------------------------------------------------
  FOR v_rec IN
    SELECT r.id, r.descricao, r.created_at
      FROM public.recomendacoes r
      JOIN public.unidades_fiscalizadas uf ON uf.id = r.unidade_fiscalizada_id
     WHERE uf.fiscalizacao_id = p_fiscalizacao_id
       AND r.descricao IS NOT NULL
       AND r.descricao <> ''
       AND NOT EXISTS (
             SELECT 1
               FROM public.caters_recommendations cr
              WHERE cr.process_id      = p_caters_process_id
                AND cr.recomendacao_id = r.id
           )
  LOOP
    INSERT INTO public.caters_recommendations (
      process_id,
      recomendacao_id,
      description,
      promised_due_at,
      priority,
      status,
      created_by
    ) VALUES (
      p_caters_process_id,
      v_rec.id,
      v_rec.descricao,
      v_prazo_date,
      'media',
      'pendente',
      auth.uid()
    );
    v_imported := v_imported + 1;
  END LOOP;

  -- ----------------------------------------------------------------
  -- Importar DETERMINAÇÕES (futuro — já preparado)
  -- determinacoes têm prazo DATE explícito; usamos ele diretamente.
  -- ----------------------------------------------------------------
  FOR v_det IN
    SELECT d.id, d.descricao, d.prazo
      FROM public.determinacoes d
      JOIN public.unidades_fiscalizadas uf ON uf.id = d.unidade_fiscalizada_id
     WHERE uf.fiscalizacao_id = p_fiscalizacao_id
       AND d.descricao IS NOT NULL
       AND d.descricao <> ''
       AND NOT EXISTS (
             SELECT 1
               FROM public.caters_recommendations cr
              WHERE cr.process_id     = p_caters_process_id
                AND cr.determinacao_id = d.id
           )
  LOOP
    INSERT INTO public.caters_recommendations (
      process_id,
      determinacao_id,
      description,
      promised_due_at,
      priority,
      status,
      created_by
    ) VALUES (
      p_caters_process_id,
      v_det.id,
      v_det.descricao,
      COALESCE(v_det.prazo, v_prazo_date),
      'alta',   -- determinações têm prioridade mais alta por padrão
      'pendente',
      auth.uid()
    );
    v_imported := v_imported + 1;
  END LOOP;

  -- Vincula o processo à fiscalização (garante consistência)
  UPDATE public.caters_processes
     SET fiscalizacao_id = p_fiscalizacao_id
   WHERE id = p_caters_process_id;

  RETURN v_imported;
END;
$function$
", "linguagem": "plpgsql", "argumentos": "p_fiscalizacao_id uuid, p_caters_process_id uuid, p_prazo_dias integer", "comentario": null, "configuracao": ["search_path=public"], "volatilidade": "volatile", "security_definer": true}, {"nome": "caters_set_updated_at", "tipo": "funcao", "esquema": "public", "retorno": "trigger", "definicao": "CREATE OR REPLACE FUNCTION public.caters_set_updated_at()
