", "linguagem": "plpgsql", "argumentos": "", "comentario": null, "configuracao": null, "volatilidade": "volatile", "security_definer": false}, {"nome": "claim_caters_ai_jobs", "tipo": "funcao", "esquema": "public", "retorno": "SETOF caters_ai_jobs", "definicao": "CREATE OR REPLACE FUNCTION public.claim_caters_ai_jobs(p_limit integer, p_job_id uuid DEFAULT NULL::uuid, p_stale_minutes integer DEFAULT 5)
 RETURNS SETOF caters_ai_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  UPDATE public.caters_ai_jobs j
  SET status = 'processing', updated_at = now(), error_message = NULL
  FROM (
    SELECT id FROM public.caters_ai_jobs
    WHERE (
        (p_job_id IS NULL OR id = p_job_id)
        AND (
          status = 'queued'
          OR (status = 'processing' AND updated_at < now() - (p_stale_minutes || ' minutes')::interval)
        )
      )
    ORDER BY created_at ASC
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  ) claimable
  WHERE j.id = claimable.id
  RETURNING j.*;
END;
$function$
