", "linguagem": "plpgsql", "argumentos": "p_limit integer, p_job_id uuid, p_stale_minutes integer", "comentario": null, "configuracao": ["search_path=public"], "volatilidade": "volatile", "security_definer": true}, {"nome": "confirm_email_on_approval", "tipo": "funcao", "esquema": "public", "retorno": "trigger", "definicao": "CREATE OR REPLACE FUNCTION public.confirm_email_on_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Se o usuário foi ativado (ativo mudou de false para true)
  IF NEW.ativo = TRUE AND OLD.ativo = FALSE THEN
    -- Atualiza a tabela auth.users para confirmar o email
    UPDATE auth.users
    SET email_confirmed_at = NOW()
    WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$
