", "linguagem": "plpgsql", "argumentos": "p_unidade_fiscalizada_id uuid, p_fotos jsonb, p_finalizar boolean", "comentario": null, "configuracao": ["search_path=public"], "volatilidade": "volatile", "security_definer": true}, {"nome": "gerar_numero_am", "tipo": "funcao", "esquema": "public", "retorno": "text", "definicao": "CREATE OR REPLACE FUNCTION public.gerar_numero_am()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  ano text;
  seq int;
BEGIN
  ano := to_char(now(), 'YYYY');
  SELECT COALESCE(count(*), 0) + 1
    INTO seq
  FROM public.termos_notificacao
  WHERE numero_am IS NOT NULL
    AND numero_am <> ''
    AND to_char(created_at, 'YYYY') = ano;

  RETURN 'AM ' || lpad(seq::text, 3, '0') || '/' || ano || '/DSB/AGEMS';
END;
$function$
", "linguagem": "plpgsql", "argumentos": "", "comentario": null, "configuracao": null, "volatilidade": "volatile", "security_definer": false}, {"nome": "gerar_numero_auto", "tipo": "funcao", "esquema": "public", "retorno": "text", "definicao": "CREATE OR REPLACE FUNCTION public.gerar_numero_auto()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    ano TEXT := to_char(NOW(), 'YYYY');
    seq INTEGER;
    novo_numero TEXT;
BEGIN
    SELECT COUNT(*) + 1 INTO seq FROM public.autos_infracao WHERE to_char(created_at, 'YYYY') = ano;
    novo_numero := 'AI ' || lpad(seq::text, 3, '0') || '/' || ano || '/DSB/AGEMS';
    RETURN novo_numero;
END;
$function$
