", "linguagem": "sql", "argumentos": "", "comentario": null, "configuracao": ["search_path=public"], "volatilidade": "stable", "security_definer": true}, {"nome": "process_audit_log", "tipo": "funcao", "esquema": "public", "retorno": "trigger", "definicao": "CREATE OR REPLACE FUNCTION public.process_audit_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id uuid;
  v_email text;
  v_requested_by text;
BEGIN
  -- Identifica o ID do usuário executor
  v_user_id := auth.uid();

  -- Se for uma Edge Function via service role executando relatorios_jobs,
  -- usa to_jsonb() para acessar o campo de forma segura (sem quebrar em outras tabelas)
  IF v_user_id IS NULL AND TG_TABLE_NAME = 'relatorios_jobs' THEN
    v_requested_by := to_jsonb(NEW)->>'requested_by';
    IF v_requested_by IS NOT NULL THEN
      v_user_id := v_requested_by::uuid;
    END IF;
  END IF;

  -- Resolve o e-mail a partir do perfil
  IF v_user_id IS NOT NULL THEN
    SELECT email INTO v_email FROM public.profiles WHERE id = v_user_id;
    IF v_email IS NULL THEN
      v_email := COALESCE(
        auth.jwt() ->> 'email',
        (SELECT email FROM auth.users WHERE id = v_user_id)
      );
    END IF;
  END IF;

  INSERT INTO public.audit_logs (
    table_name,
    record_id,
    action,
    user_id,
    user_email,
    old_data,
    new_data
  )
  VALUES (
    TG_TABLE_NAME,
    COALESCE(NEW.id, OLD.id),
    TG_OP,
    v_user_id,
    v_email,
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END
  );

  RETURN COALESCE(NEW, OLD);
END;
$function$
", "linguagem": "plpgsql", "argumentos": "", "comentario": null, "configuracao": null, "volatilidade": "volatile", "security_definer": true}, {"nome": "propagate_modification_to_parent", "tipo": "funcao", "esquema": "public", "retorno": "trigger", "definicao": "CREATE OR REPLACE FUNCTION public.propagate_modification_to_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_fiscalizacao_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'unidades_fiscalizadas' THEN
    v_fiscalizacao_id := COALESCE(NEW.fiscalizacao_id, OLD.fiscalizacao_id);
  ELSIF TG_TABLE_NAME IN ('respostas_checklist', 'constatacoes_manuais', 'recomendacoes', 'determinacoes') THEN
    SELECT fiscalizacao_id INTO v_fiscalizacao_id
    FROM public.unidades_fiscalizadas
    WHERE id = COALESCE(NEW.unidade_fiscalizada_id, OLD.unidade_fiscalizada_id);
  END IF;

  IF v_fiscalizacao_id IS NOT NULL THEN
    UPDATE public.fiscalizacoes
    SET updated_at = now()
    WHERE id = v_fiscalizacao_id;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
